import json

MOD = 0x11B  # x^8+x^4+x^3+x+1, irreducible over F_2 (GF(256))

def mul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        if a & 0x100:
            a ^= MOD
        b >>= 1
    return r

def power(a, e):
    r = 1
    while e:
        if e & 1:
            r = mul(r, a)
        a = mul(a, a)
        e >>= 1
    return r

def subfield(j):
    # elements of GF(2^j) inside GF(256): a^(2^j) == a
    return [a for a in range(256) if power(a, 2 ** j) == a]

checks = {}
ok_all = True
for j in (1, 2, 4):
    F = subfield(j)
    ok = True
    for b in F:
        for c in F:
            roots = [x for x in range(256) if mul(x, x) ^ mul(b, x) ^ c == 0]
            # in char 2 the other root is x+b, so one root means it splits
            if not roots or any((r ^ b) not in roots for r in roots):
                ok = False
    checks[f"F_2^{j} sizes={len(F)}"] = ok
    ok_all = ok_all and ok

# Tower F_{2^(2^k)} strictly increasing => union infinite; every quadratic over the
# union lies over some F_{2^(2^k)} and splits in F_{2^(2^(k+1))} (degree <= 2 extension).
tower = [2 ** (2 ** k) for k in range(6)]
infinite = all(tower[i] < tower[i + 1] for i in range(len(tower) - 1))

if ok_all and infinite:
    ans = "Yes"
else:
